CREATE TABLE workspaces(id uuid PRIMARY KEY,name text NOT NULL,mode text NOT NULL CHECK(mode IN ('SIMULATION','PAYPAL_SANDBOX')),merchant_id text NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('OWNER','OPERATOR','VIEWER')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions(id uuid PRIMARY KEY,token_hash text UNIQUE NOT NULL,csrf_hash text NOT NULL,user_id uuid NOT NULL REFERENCES users(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE recall_sources(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),recall_number text NOT NULL,canonical_url text NOT NULL,UNIQUE(workspace_id,recall_number));
CREATE TABLE source_versions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),source_id uuid NOT NULL REFERENCES recall_sources(id),version integer NOT NULL,raw_json jsonb NOT NULL,raw_snapshot text NOT NULL,documents jsonb NOT NULL,content_hash text NOT NULL,source_date text NOT NULL,fetched_at timestamptz NOT NULL,freshness_checked_at timestamptz,freshness_status text NOT NULL,origin text NOT NULL,UNIQUE(source_id,version));
CREATE TABLE extractions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),source_version_id uuid NOT NULL REFERENCES source_versions(id),schema_version text NOT NULL DEFAULT '1',prompt_version text NOT NULL,model text NOT NULL,provider_response_id text,candidate jsonb,validation_errors jsonb NOT NULL DEFAULT '[]',status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviewed_rules(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),source_version_id uuid NOT NULL REFERENCES source_versions(id),extraction_id uuid NOT NULL REFERENCES extractions(id),revision integer NOT NULL,rule jsonb NOT NULL,rule_hash text NOT NULL,reviewer_id uuid NOT NULL REFERENCES users(id),review_note text NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,superseded_at timestamptz,revoked_at timestamptz);
CREATE TABLE merchant_policies(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),revision integer NOT NULL,policy jsonb NOT NULL,policy_hash text NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX merchant_policy_one_active ON merchant_policies(workspace_id) WHERE active=true;
CREATE TABLE orders(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),display_id text NOT NULL,customer_label text NOT NULL,customer_email text NOT NULL,total_minor bigint NOT NULL CHECK(total_minor>0),currency text NOT NULL,tax_minor bigint NOT NULL DEFAULT 0,shipping_minor bigint NOT NULL DEFAULT 0,discount_minor bigint NOT NULL DEFAULT 0,data_origin text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,display_id));
CREATE TABLE order_items(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),order_id uuid NOT NULL REFERENCES orders(id),brand text,model text,title text NOT NULL,serial text,date_code text,normalized_brand text,normalized_model text,quantity integer NOT NULL CHECK(quantity>0),unit_minor bigint NOT NULL CHECK(unit_minor>0),customer_note text);
CREATE TABLE payment_links(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),mode text NOT NULL CHECK(mode IN ('SIMULATION','PAYPAL_SANDBOX')),order_id uuid NOT NULL REFERENCES orders(id),provider_order_id text,capture_id text,merchant_id text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL,verified_state text NOT NULL,owned boolean NOT NULL DEFAULT false,last_snapshot jsonb,verified_at timestamptz,create_request_id uuid NOT NULL UNIQUE,capture_request_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id));
CREATE UNIQUE INDEX payment_link_capture_once ON payment_links(mode,capture_id) WHERE capture_id IS NOT NULL;
CREATE TABLE cases(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),order_item_id uuid NOT NULL REFERENCES order_items(id),source_version_id uuid NOT NULL REFERENCES source_versions(id),rule_id uuid NOT NULL REFERENCES reviewed_rules(id),revision integer NOT NULL DEFAULT 1,match_state text NOT NULL CHECK(match_state IN ('EXACT_MATCH','NEEDS_REVIEW','NOT_MATCHED_TO_NOTICE')),match_reasons jsonb NOT NULL,official_remedy_state text NOT NULL DEFAULT 'EXTERNAL_FOLLOWUP_REQUIRED',courtesy_state text NOT NULL DEFAULT 'NOT_ELIGIBLE',scenario text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_proposals(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),case_id uuid NOT NULL REFERENCES cases(id),case_revision integer NOT NULL,payment_link_id uuid NOT NULL REFERENCES payment_links(id),source_version_id uuid NOT NULL REFERENCES source_versions(id),rule_id uuid NOT NULL REFERENCES reviewed_rules(id),policy_id uuid NOT NULL REFERENCES merchant_policies(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency='USD'),canonical text NOT NULL,fingerprint text NOT NULL,eligibility_reasons jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approvals(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),proposal_id uuid NOT NULL UNIQUE REFERENCES refund_proposals(id),approver_id uuid NOT NULL REFERENCES users(id),approved_fingerprint text NOT NULL,note text NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE payment_attempts(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),approval_id uuid NOT NULL REFERENCES approvals(id),case_id uuid NOT NULL REFERENCES cases(id),capture_id text NOT NULL,mode text NOT NULL CHECK(mode IN ('SIMULATION','PAYPAL_SANDBOX')),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency='USD'),paypal_request_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('RESERVED','PREFLIGHT','DISPATCHING','PROVIDER_PENDING','COMPLETED','FAILED_FINAL','CANCELLED_FINAL','OUTCOME_UNKNOWN','BLOCKED_BEFORE_DISPATCH')),dispatch_started_at timestamptz,provider_refund_id text,provider_status text,failure_code text,provider_snapshot jsonb,verification_stale boolean NOT NULL DEFAULT false,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX payment_attempt_capture_once ON payment_attempts(workspace_id,mode,capture_id);
CREATE UNIQUE INDEX payment_attempt_request_once ON payment_attempts(paypal_request_id);
CREATE UNIQUE INDEX payment_attempt_refund_once ON payment_attempts(mode,provider_refund_id) WHERE provider_refund_id IS NOT NULL;
CREATE TABLE jobs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'READY',attempts integer NOT NULL DEFAULT 0,run_after timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,locked_by text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON jobs(run_after) WHERE status='READY';
CREATE TABLE audit_events(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),actor_type text NOT NULL,actor_id text NOT NULL,event_type text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,correlation_id uuid NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE demo_evidence_runs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),mode text NOT NULL CHECK(mode='RECORDED_SANDBOX_EVIDENCE'),case_id uuid NOT NULL REFERENCES cases(id),attempt_id uuid NOT NULL REFERENCES payment_attempts(id),evidence jsonb NOT NULL,build_commit text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fixture_provider_events(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),attempt_id uuid NOT NULL REFERENCES payment_attempts(id),operation text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION protect_workspace_mode() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.mode<>OLD.mode THEN RAISE EXCEPTION 'Workspace mode is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER workspace_mode_immutable BEFORE UPDATE ON workspaces FOR EACH ROW EXECUTE FUNCTION protect_workspace_mode();
CREATE FUNCTION immutable_payload() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Evidence payload is immutable'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_payload();
CREATE TRIGGER proposal_immutable BEFORE UPDATE OR DELETE ON refund_proposals FOR EACH ROW EXECUTE FUNCTION immutable_payload();
CREATE FUNCTION protect_version_payload() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='source_versions' AND (NEW.raw_json<>OLD.raw_json OR NEW.raw_snapshot<>OLD.raw_snapshot OR NEW.documents<>OLD.documents OR NEW.content_hash<>OLD.content_hash OR NEW.source_id<>OLD.source_id OR NEW.version<>OLD.version OR NEW.source_date<>OLD.source_date OR NEW.fetched_at<>OLD.fetched_at OR NEW.origin<>OLD.origin) THEN RAISE EXCEPTION 'Source content is immutable'; END IF;
 IF TG_TABLE_NAME='reviewed_rules' AND (NEW.rule<>OLD.rule OR NEW.rule_hash<>OLD.rule_hash OR NEW.source_version_id<>OLD.source_version_id OR NEW.extraction_id<>OLD.extraction_id OR NEW.reviewer_id<>OLD.reviewer_id OR NEW.review_note<>OLD.review_note OR NEW.expires_at<>OLD.expires_at OR NEW.reviewed_at<>OLD.reviewed_at) THEN RAISE EXCEPTION 'Reviewed rule is immutable'; END IF;
 IF TG_TABLE_NAME='approvals' AND (NEW.proposal_id<>OLD.proposal_id OR NEW.approved_fingerprint<>OLD.approved_fingerprint OR NEW.approver_id<>OLD.approver_id OR NEW.expires_at<>OLD.expires_at OR NEW.note<>OLD.note OR NEW.approved_at<>OLD.approved_at) THEN RAISE EXCEPTION 'Approval payload is immutable'; END IF;
 IF TG_TABLE_NAME='merchant_policies' AND (NEW.policy<>OLD.policy OR NEW.policy_hash<>OLD.policy_hash OR NEW.owner_id<>OLD.owner_id OR NEW.revision<>OLD.revision) THEN RAISE EXCEPTION 'Policy payload is immutable'; END IF;
 IF NEW.workspace_id<>OLD.workspace_id THEN RAISE EXCEPTION 'Workspace ownership is immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER source_payload_immutable BEFORE UPDATE ON source_versions FOR EACH ROW EXECUTE FUNCTION protect_version_payload();
CREATE TRIGGER rule_payload_immutable BEFORE UPDATE ON reviewed_rules FOR EACH ROW EXECUTE FUNCTION protect_version_payload();
CREATE TRIGGER approval_payload_immutable BEFORE UPDATE ON approvals FOR EACH ROW EXECUTE FUNCTION protect_version_payload();
CREATE TRIGGER policy_payload_immutable BEFORE UPDATE ON merchant_policies FOR EACH ROW EXECUTE FUNCTION protect_version_payload();
CREATE FUNCTION protect_attempt_payload() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.workspace_id<>OLD.workspace_id OR NEW.approval_id<>OLD.approval_id OR NEW.case_id<>OLD.case_id OR NEW.capture_id<>OLD.capture_id OR NEW.mode<>OLD.mode OR NEW.amount_minor<>OLD.amount_minor OR NEW.currency<>OLD.currency OR NEW.paypal_request_id<>OLD.paypal_request_id THEN RAISE EXCEPTION 'Attempt identity is immutable'; END IF;
 IF OLD.dispatch_started_at IS NOT NULL AND NEW.dispatch_started_at IS DISTINCT FROM OLD.dispatch_started_at THEN RAISE EXCEPTION 'Dispatch cannot be reset'; END IF;
 IF OLD.dispatch_started_at IS NOT NULL AND NEW.status IN ('RESERVED','PREFLIGHT') THEN RAISE EXCEPTION 'Dispatched writes cannot be retried'; END IF;
 IF OLD.status IN ('COMPLETED','FAILED_FINAL','CANCELLED_FINAL') AND NEW.status<>OLD.status THEN RAISE EXCEPTION 'Final attempt cannot be downgraded'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER attempt_payload_immutable BEFORE UPDATE ON payment_attempts FOR EACH ROW EXECUTE FUNCTION protect_attempt_payload();
CREATE FUNCTION validate_link_mode() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.mode<>(SELECT mode FROM workspaces WHERE id=NEW.workspace_id) THEN RAISE EXCEPTION 'Payment mode mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_link_mode BEFORE INSERT OR UPDATE ON payment_links FOR EACH ROW EXECUTE FUNCTION validate_link_mode();
